122	    public int loadStatsRangeEnd() {
123	        assert partitionLoadStats != null;
124	        assert partitionLoadStats.length > 0;
125	        return partitionLoadStats.cumulativeFrequencyTable[partitionLoadStats.length - 1];
126	    }
