128	    /**
129	     * Peek currently chosen sticky partition.  This method works in conjunction with {@link #isPartitionChanged}
130	     * and {@link #updatePartitionInfo}.  The workflow is the following:
131	     *
132	     * 1. peekCurrentPartitionInfo is called to know which partition to lock.
133	     * 2. Lock partition's batch queue.
134	     * 3. isPartitionChanged under lock to make sure that nobody raced us.
135	     * 4. Append data to buffer.
136	     * 5. updatePartitionInfo to update produced bytes and maybe switch partition.
137	     *
138	     *  It's important that steps 3-5 are under partition's batch queue lock.
139	     *
140	     * @param cluster The cluster information (needed if there is no current partition)
141	     * @return sticky partition info object
142	     */
143	    StickyPartitionInfo peekCurrentPartitionInfo(Cluster cluster) {
144	        StickyPartitionInfo partitionInfo = stickyPartitionInfo.get();
145	        if (partitionInfo != null)
146	            return partitionInfo;
147	
148	        // We're the first to create it.
149	        partitionInfo = new StickyPartitionInfo(nextPartition(cluster));
150	        if (stickyPartitionInfo.compareAndSet(null, partitionInfo))
151	            return partitionInfo;
152	
153	        // Someone has raced us.
154	        return stickyPartitionInfo.get();
155	    }
